"""Component for fetching Jira issue details."""

from __future__ import annotations

import asyncio
import re
from contextlib import suppress
from typing import Any, Iterable, Sequence
from urllib.parse import parse_qs, urlparse

from jira import JIRA
from jira.exceptions import JIRAError

from lfx.custom.custom_component.component import Component
from lfx.io import MessageTextInput, Output, SecretStrInput, StrInput
from lfx.schema.data import Data
from lfx.schema.message import Message


class JiraGetTaskComponent(Component):
    """Fetch a Jira issue description and comments using its URL."""

    display_name = "Jira Get Task"
    description = "Retrieve a Jira issue summary, description, and comments from a task URL."
    documentation = "https://developer.atlassian.com/cloud/jira/platform/rest/v3/api-group-issues/"
    icon = "Jira"

    ISSUE_KEY_RE = re.compile(r"([A-Z][A-Z0-9_]+-\d+)", re.IGNORECASE)
    STOP_SEGMENTS = {
        "browse",
        "projects",
        "issues",
        "secure",
        "board",
        "boards",
        "rapidboard",
        "wiki",
        "page",
        "portal",
        "customer",
        "servicedesk",
        "ticket",
        "view",
    }

    inputs = [
        MessageTextInput(
            name="task_url",
            display_name="Issue URL",
            info="Direct link to the Jira issue (e.g., https://your-domain.atlassian.net/browse/KEY-123).",
            required=True,
        ),
        StrInput(
            name="jira_email",
            display_name="Account Email or Username",
            info="Jira account email (Cloud) or username (Server) associated with the API token.",
            required=True,
        ),
        SecretStrInput(
            name="jira_api_token",
            display_name="Jira API Token",
            info="Jira API token (https://id.atlassian.com/manage-profile/security/api-tokens).",
            required=True,
            value="JIRA_API_TOKEN",
        ),
    ]

    outputs = [
        Output(display_name="Task Details", name="task_details", method="get_task_details"),
        Output(display_name="Task Description", name="task_description", method="get_task_description"),
    ]

    timeout_seconds: float = 15.0

    async def get_task_description(self) -> Message:
        """Return the Jira issue as formatted text for use as a message/prompt."""
        data = await self.get_task_details()
        if "error" in data.data:
            raise ValueError(data.data["error"])

        details = data.data
        lines = [
            f"# {details['issue_key']}: {details['summary']}",
            f"URL: {details['issue_url']}",
            f"Status: {details['status']}",
            "",
            "## Description",
            details['description'] or "(No description)",
        ]

        comments = details.get("comments", [])
        if comments:
            lines.append("")
            lines.append("## Comments")
            for comment in comments:
                lines.append(f"\n### {comment['author']} ({comment['created']})")
                lines.append(comment['body'])

        text = "\n".join(lines)
        return Message(text=text)

    async def get_task_details(self) -> Data:
        """Return the Jira issue description and comments."""
        try:
            task_url = (self.task_url or "").strip()
            email = (self.jira_email or "").strip()
            token = (self.jira_api_token or "").strip()
        except AttributeError as exc:  # pragma: no cover - defensive, Component always sets attributes
            error = {"error": f"Missing component input: {exc}"}
            self.status = error
            return Data(data=error)

        if not task_url:
            error = {"error": "Task URL is required."}
            self.status = error
            return Data(data=error)

        if not email or not token:
            error = {"error": "Both Jira account email/username and API token must be provided."}
            self.status = error
            return Data(data=error)

        try:
            parsed_url = urlparse(task_url)
            issue_key = self._extract_issue_key(parsed_url)
            base_candidates = self._candidate_base_urls(parsed_url, issue_key)
        except ValueError as exc:
            error = {"error": str(exc)}
            self.status = error
            return Data(data=error)

        try:
            processed = await asyncio.to_thread(
                self._fetch_issue_details,
                base_candidates,
                issue_key,
                email,
                token,
                task_url,
            )
        except PermissionError as exc:
            error = {"error": str(exc)}
            self.status = error
            return Data(data=error)
        except JIRAError as exc:
            error = {"error": self._format_jira_error(exc, issue_key)}
            self.status = error
            return Data(data=error)
        except Exception as exc:  # noqa: BLE001
            error = {"error": f"Failed to retrieve Jira issue '{issue_key}': {exc}"}
            self.status = error
            return Data(data=error)

        self.status = processed
        return Data(data=processed)

    @classmethod
    def _extract_issue_key(cls, parsed_url) -> str:
        """Extract the Jira issue key from the parsed URL."""
        # Check path segments
        for segment in cls._iter_url_values(parsed_url.path):
            match = cls.ISSUE_KEY_RE.search(segment)
            if match:
                return match.group(1).upper()

        # Check query string values
        for values in parse_qs(parsed_url.query, keep_blank_values=False).values():
            for value in values:
                match = cls.ISSUE_KEY_RE.search(value)
                if match:
                    return match.group(1).upper()

        # Check fragment
        if parsed_url.fragment:
            match = cls.ISSUE_KEY_RE.search(parsed_url.fragment)
            if match:
                return match.group(1).upper()

        raise ValueError("Could not detect a Jira issue key in the provided URL.")

    @classmethod
    def _candidate_base_urls(cls, parsed_url, issue_key: str) -> list[str]:
        """Generate potential API base URLs, including optional context paths."""
        base = f"{parsed_url.scheme}://{parsed_url.netloc}"
        candidates = [base.rstrip("/")]
        segments = [segment for segment in cls._iter_url_values(parsed_url.path) if segment]
        current = base.rstrip("/")

        for segment in segments:
            lowered = segment.lower()
            if lowered in cls.STOP_SEGMENTS or segment.upper() == issue_key:
                break
            current = f"{current}/{segment}"
            candidates.append(current)

        # Remove duplicates while preserving order
        seen: set[str] = set()
        ordered_candidates: list[str] = []
        for candidate in candidates:
            if candidate not in seen:
                seen.add(candidate)
                ordered_candidates.append(candidate)
        return ordered_candidates

    def _fetch_issue_details(
        self,
        base_candidates: Sequence[str],
        issue_key: str,
        email: str,
        token: str,
        original_url: str,
    ) -> dict[str, Any]:
        """Synchronous helper that talks to the Jira REST API via the official SDK."""
        last_error: Exception | None = None

        for base_url in base_candidates:
            client: JIRA | None = None
            try:
                # The JIRA library handles the REST API path internally
                client = JIRA(
                    server=base_url,
                    basic_auth=(email, token),
                    timeout=self.timeout_seconds,
                )
                issue = client.issue(issue_key, expand="renderedFields,names")
                comments = client.comments(issue)

                raw_issue = issue.raw
                raw_comments: list[dict[str, Any]] = []
                for comment in comments or []:
                    raw = getattr(comment, "raw", None)
                    if isinstance(raw, dict):
                        raw_comments.append(raw)
                    else:
                        author = getattr(comment, "author", None)
                        raw_comments.append(
                            {
                                "id": getattr(comment, "id", None),
                                "author": {
                                    "displayName": getattr(author, "displayName", "") if author else "",
                                    "emailAddress": getattr(author, "emailAddress", "") if author else "",
                                },
                                "created": getattr(comment, "created", None),
                                "updated": getattr(comment, "updated", None),
                                "body": getattr(comment, "body", ""),
                            }
                        )

                return self._build_response(raw_issue, raw_comments, issue_key, original_url)
            except JIRAError as exc:
                if getattr(exc, "status_code", None) in {401, 403}:
                    msg = (
                        "Jira authentication failed. Please verify the account email/username "
                        "and API token."
                    )
                    raise PermissionError(msg) from exc
                last_error = exc
            except Exception as exc:  # noqa: BLE001
                last_error = exc
            finally:
                if client is not None:
                    with suppress(Exception):
                        client.close()

        if isinstance(last_error, JIRAError):
            raise last_error
        if last_error is not None:
            raise last_error
        raise RuntimeError(f"Failed to retrieve Jira issue '{issue_key}' for unknown reasons.")

    @staticmethod
    def _iter_url_values(path: str) -> Iterable[str]:
        """Yield non-empty URL segments or raw string when not slash-separated."""
        if not path:
            return []
        if "/" not in path:
            return [path]
        return [segment for segment in path.split("/") if segment]

    @staticmethod
    def _format_jira_error(exc: JIRAError, issue_key: str) -> str:
        """Create a user-friendly error message from a JIRAError."""
        status = getattr(exc, "status_code", None)
        text = (getattr(exc, "text", "") or str(exc)).strip()
        if status:
            base = f"Jira API returned status {status} while retrieving issue '{issue_key}'."
        else:
            base = f"Jira API error while retrieving issue '{issue_key}'."
        if text:
            return f"{base} Details: {text}"
        return base

    def _build_response(
        self,
        issue_data: dict[str, Any],
        comments: Sequence[dict[str, Any]],
        issue_key: str,
        original_url: str,
    ) -> dict[str, Any]:
        """Shape issue and comment payload into the component response."""
        fields = issue_data.get("fields", {})
        description_raw = fields.get("description")
        description = self._adf_to_text(description_raw).strip()
        summary = fields.get("summary") or ""
        status_name = (fields.get("status") or {}).get("name")

        parsed_comments = []
        for item in comments or []:
            body_text = self._adf_to_text(item.get("body")).strip()
            author = item.get("author") or {}
            display_name = author.get("displayName") or author.get("emailAddress") or ""
            parsed_comments.append(
                {
                    "id": item.get("id"),
                    "author": display_name,
                    "created": item.get("created"),
                    "updated": item.get("updated"),
                    "body": body_text,
                }
            )

        issue_details = {
            "issue_key": issue_key,
            "issue_url": original_url,
            "summary": summary,
            "description": description,
            "status": status_name,
            "comments": parsed_comments,
        }
        return issue_details

    @classmethod
    def _adf_to_text(cls, node: Any) -> str:
        """Convert Atlassian Document Format content into plaintext."""
        if node is None:
            return ""
        if isinstance(node, str):
            return node
        if isinstance(node, list):
            parts = [cls._adf_to_text(child) for child in node]
            return "\n".join(part for part in parts if part)
        if isinstance(node, dict):
            node_type = node.get("type")
            content = node.get("content") or []

            if node_type == "text":
                text = node.get("text", "")
                for mark in node.get("marks") or []:
                    if mark.get("type") == "link":
                        href = (mark.get("attrs") or {}).get("href")
                        if href:
                            text = f"{text} ({href})" if text else href
                return text

            if node_type == "mention":
                attrs = node.get("attrs") or {}
                return attrs.get("text") or attrs.get("id") or ""

            if node_type == "emoji":
                attrs = node.get("attrs") or {}
                return attrs.get("text") or attrs.get("shortName") or ""

            if node_type == "hardBreak":
                return "\n"

            if node_type in {"paragraph", "blockCard", "inlineCard"}:
                return cls._collapse_lines(cls._adf_to_text(content))

            if node_type == "heading":
                text = cls._collapse_lines(cls._adf_to_text(content))
                return text.upper() if text else ""

            if node_type in {"bulletList", "orderedList"}:
                items = []
                is_ordered = node_type == "orderedList"
                start = (node.get("attrs") or {}).get("order", 1)
                for index, item in enumerate(content or [], start=start):
                    text = cls._collapse_lines(cls._adf_to_text(item)).strip()
                    if not text:
                        continue
                    prefix = f"{index}. " if is_ordered else "- "
                    items.append(f"{prefix}{text}")
                return "\n".join(items)

            if node_type == "listItem":
                return cls._collapse_lines(cls._adf_to_text(content))

            if node_type == "table":
                rows = []
                for row in content:
                    rows.append(cls._collapse_lines(cls._adf_to_text(row)))
                return "\n".join(rows)

            if node_type == "tableRow":
                cells = []
                for idx, cell in enumerate(content or [], start=1):
                    text = cls._collapse_lines(cls._adf_to_text(cell)).strip()
                    cells.append(f"{idx}. {text}" if text else "")
                return " | ".join(filter(None, cells))

            if node_type in {"tableCell", "tableHeader"}:
                return cls._collapse_lines(cls._adf_to_text(content))

            if node_type == "codeBlock":
                text = cls._collapse_lines(cls._adf_to_text(content))
                return f"\n{text}\n"

            if node_type == "panel":
                text = cls._collapse_lines(cls._adf_to_text(content))
                return text

            if node_type == "doc":
                return cls._collapse_lines(cls._adf_to_text(content))

            # Default: flatten nested content
            return cls._collapse_lines(cls._adf_to_text(content))

        return str(node)

    @staticmethod
    def _collapse_lines(text: str) -> str:
        """Reduce consecutive blank lines to a single newline."""
        if not text:
            return ""
        # Split on newline, strip trailing spaces, and drop empty segments intelligently.
        lines = [line.rstrip() for line in text.splitlines()]
        collapsed: list[str] = []
        for line in lines:
            if line or (collapsed and collapsed[-1]):
                collapsed.append(line)
        return "\n".join(collapsed).strip("\n")


